{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Adult patients ≥18 years of age (or the legal age of adults to consent to participate in a clinical study per country specific regulations).",
      "quote": "Adult patients ≥18 years of age (or the legal age of adults to consent to participate in a clinical study per country specific regulations).",
      "thresholds": [
        {
          "test": "age",
          "op": ">=",
          "value": 18,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Has histologically confirmed recurrent or metastatic HPV16 positive cervical cancer as determined by an investigational HPV16 PCR assay by Qiagen, who have experienced disease progression after treatment with platinum containing therapy (must have been used to treat metastatic, persistent, or recurrent cervical cancer).",
      "quote": "Has histologically confirmed recurrent or metastatic HPV16 positive cervical cancer as determined by an investigational HPV16 PCR assay by Qiagen, who have experienced disease progression after treatment with platinum containing therapy",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patient must be determined to be positive for HPV16 genotype, as determined by a specified central reference laboratory.",
      "quote": "Patient must be determined to be positive for HPV16 genotype, as determined by a specified central reference laboratory.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patient must have measurable disease as defined by RECIST 1.1. Measurable disease is defined as at least 1 lesion that can be accurately measured in at least 1 dimension (longest dimension to be recorded). Each lesion must be ≥10 mm when measured by computed tomography (CT), magnetic resonance imaging (MRI), or caliper measurement by clinical exam or must be ≥20 mm when measured by chest x-ray. Lymph nodes must be ≥15 mm in short axis when measured by CT or MRI.",
      "quote": "Patient must have measurable disease as defined by RECIST 1.1.",
      "thresholds": [
        {
          "test": "lesion size (CT/MRI/caliper)",
          "op": ">=",
          "value": 10,
          "unit": "mm"
        },
        {
          "test": "lesion size (chest x-ray)",
          "op": ">=",
          "value": 20,
          "unit": "mm"
        },
        {
          "test": "lymph node short axis",
          "op": ">=",
          "value": 15,
          "unit": "mm"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Patients must meet at least 1 of the following criteria regarding prior bevacizumab therapy: a. Received prior bevacizumab-containing therapy and experienced subsequent progression of disease; b. Received prior bevacizumab-containing therapy which was discontinued due to toxicity; c. Was unsuitable for bevacizumab due to i) unacceptable risk of fistula formation, ii) poorly controlled hypertension, iii) low risk disease according to Moore criteria; d. Refused prior bevacizumab; e. Did not have access to bevacizumab.",
      "quote": "Patients must meet at least 1 of the following criteria regarding prior bevacizumab therapy:",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients must meet at least 1 of the following criteria regarding prior taxol therapy: a. Received prior taxol-containing therapy and experienced subsequent progression of disease; b. Received prior taxol-containing therapy which was discontinued due to toxicity; c. Was unsuitable for taxol therapy due to i) neuropathy, ii) allergy or intolerance to taxol or one of its components; d. Refused prior taxol.",
      "quote": "Patients must meet at least 1 of the following criteria regarding prior taxol therapy",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "ECOG performance status of 0 or 1.",
      "quote": "ECOG performance status of 0 or 1.",
      "thresholds": [
        {
          "test": "ECOG performance status",
          "op": "<=",
          "value": 1
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Has adequate organ and bone marrow function documented by: a. Hemoglobin ≥16 g/dL; b. Absolute neutrophil count ≥1.0 x 10^9/L; c. Platelet count ≥75 x 10^9/L; d. Serum creatinine ≤1.5 x upper limit of normal (ULN) or estimated glomerular filtration rate >30 mL/min/1.73m2; e. Adequate hepatic function: (i) Total bilirubin ≤1.5 x ULN (≤3 x ULN if tumor liver involvement); (ii) AST ≤2.5 x ULN (≤3 x ULN if tumor liver involvement); (iii) ALT ≤2.5 x ULN (≤3 x ULN if tumor liver involvement); (iv) ALP ≤2.5 x ULN (≤3 x ULN if tumor liver or bone involvement).",
      "quote": "Has adequate organ and bone marrow function documented by:",
      "thresholds": [
        {
          "test": "Hemoglobin",
          "op": ">=",
          "value": 16,
          "unit": "g/dL"
        },
        {
          "test": "Absolute neutrophil count",
          "op": ">=",
          "value": 1.0,
          "unit": "10^9/L"
        },
        {
          "test": "Platelet count",
          "op": ">=",
          "value": 75,
          "unit": "10^9/L"
        },
        {
          "test": "Serum creatinine",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "eGFR",
          "op": ">",
          "value": 30,
          "unit": "mL/min/1.73m2"
        },
        {
          "test": "Total bilirubin",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "AST",
          "op": "<=",
          "value": 2.5,
          "unit": "x ULN"
        },
        {
          "test": "ALT",
          "op": "<=",
          "value": 2.5,
          "unit": "x ULN"
        },
        {
          "test": "ALP",
          "op": "<=",
          "value": 2.5,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Anticipated life expectancy ≥20 weeks.",
      "quote": "Anticipated life expectancy ≥20 weeks.",
      "thresholds": [
        {
          "test": "life expectancy",
          "op": ">=",
          "value": 20,
          "unit": "weeks"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Is willing and able to comply with clinic visits and study-related procedures and requirements.",
      "quote": "Is willing and able to comply with clinic visits and study-related procedures and requirements",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Able to understand and complete study-related questionnaires.",
      "quote": "Able to understand and complete study-related questionnaires",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Provide informed consent signed by study patient or legally acceptable representative.",
      "quote": "Provide informed consent signed by study patient or legally acceptable representative",
      "thresholds": []
    }
  ]
}
